 entity Prob_6_35j_Serial_Twos_Comp_vhdl is	port (y: out bit; data: in bit_vector (7 downto 0);); load, shift_control, Clock, reset_b: in bit);end Prob_6_35j_Serial_Twos_Comp_vhdl;architecture Behavioral of Prob_6_35j_Serial_Twos_Comp_vhdl is	signal Sreg: bit_vector (7 downto 0);	signal Q, SO: bit;begin  	SO <= SReg [0];	y <= SO xor Q;	process (Clock, reset_b) begin  		if (reset_b = '0') then    			SReg <= '0';    			Q <= '0';		elsif  (load = '1') then SReg <= data;     		elsif (shift_control = '1') then      		Q <= Q xor SO;      		SReg <= y & Sreg (7 downto 1]);    		end if;  end process;end Behavioral;